export function LeakyButton({ variant = 'primary', ...rest }: ButtonProps) {
  return <button className="ui-button" data-variant={variant} {...rest} />;
}

type IconButtonProps = { label: string; icon: ReactNode; ref?: Ref<HTMLButtonElement> };

function IconButton({ label, icon }: IconButtonProps) {
  return <button type="button" aria-label={label}>{icon}</button>;
}

const closeRef = createRef<HTMLButtonElement>();
render(<IconButton ref={closeRef} label="Close" icon={<CloseIcon />} />);

